UPDATE public.questions AS t
   SET original_question_text = COALESCE(t.original_question_text, t.question_text),
       original_correct_answer = COALESCE(t.original_correct_answer, t.correct_answer),
       original_incorrect_answers = COALESCE(t.original_incorrect_answers, t.incorrect_answers),
       question_text = v.stem,
       correct_answer = v.correct,
       incorrect_answers = v.wrong,
       shorten_status = 'shortened'
  FROM (VALUES
    ('d47b6566', 'Which currency became notorious in Zimbabwe''s hyperinflation?', 'Zimbabwean dollar', '["Venezuelan bol\u00edvar", "Argentine peso", "Turkish lira"]'::jsonb),
    ('d48768f3', 'What classifies a sensor by the phenomenon it detects?', 'Transduction principle', '["Output signal", "Power draw", "Application domain"]'::jsonb),
    ('d72b0368', 'Whose 1966 book laid the ground for postmodern architecture?', 'Robert Venturi', '["Frank Gehry", "I. M. Pei", "Mies van der Rohe"]'::jsonb),
    ('d8ad4185', 'Which therapy family is defined by changing thought and habit?', 'Cognitive behavioural', '["Psychodynamic", "Humanistic", "Systemic"]'::jsonb),
    ('db7bc02f', 'Which system navigates by sound, as bats do?', 'Sonar', '["Radar", "Lidar", "Infrared"]'::jsonb),
    ('df09e915', 'Which cosmology echoes the Hindu view of repeating time?', 'A cyclic universe', '["Steady state", "Big Bang", "Heat death"]'::jsonb),
    ('e0a90f8a', 'How does quantitative easing push asset prices up indirectly?', 'It pushes money into risk', '["It cuts short-term rates", "It raises state spending", "It lifts wages"]'::jsonb),
    ('e431eca2', 'Which cosmonaut took the Olympic torch to the ISS in 2013?', 'Mikhail Tyurin', '["Sunita Williams", "Chris Hadfield", "Samantha Cristoforetti"]'::jsonb),
    ('e7322064', 'Who shared the 2011 Wolf Prize for cell reprogramming?', 'John Gurdon', '["James Thomson", "Martin Evans", "Ian Wilmut"]'::jsonb),
    ('e77ee6c2', 'Which lizard changes colour and has zygodactyl feet?', 'Chameleon', '["Gecko", "Iguana", "Skink"]'::jsonb),
    ('e7d8cdb7', 'What disrupted poultry and egg supply from 2021 to 2023?', 'Bird flu', '["African swine fever", "Foot-and-mouth", "Salmon disease"]'::jsonb),
    ('e8715eec', 'Which conservation programme costs the most farmland per animal?', 'Panda breeding', '["Tiger reserves", "Elephant corridors", "Rhino patrols"]'::jsonb),
    ('ea17cd73', 'What locked engineers out during the 2021 Facebook outage?', 'The badge readers', '["The power grid", "The network cables", "A fire alarm"]'::jsonb),
    ('eb7acdc9', 'Which Worth silhouette changed 19th-century women''s dress?', 'Princess Line', '["A-line", "Empire", "Flapper"]'::jsonb),
    ('ec788a4f', 'Which body maintains the definitions of the SI units?', 'The BIPM', '["The ISO", "The IEEE", "The WMO"]'::jsonb),
    ('eddcca2a', 'Which two notations besides Big O did Knuth standardise?', 'Big Omega and Big Theta', '["Little o and little omega", "Alpha and beta", "Sigma and delta"]'::jsonb),
    ('eeecfd0d', 'Which African animal lost 90% of its numbers to horn poaching?', 'Black Rhinoceros', '["African Elephant", "Giant Panda", "Koala"]'::jsonb),
    ('ef219fb0', 'Which GIF trait made it the format of looping memes?', 'It replays by itself', '["High resolution", "Embedded audio", "Vector scaling"]'::jsonb),
    ('f059e7bd', 'Which space technology sharpened Olympic timing?', 'Atomic clocks', '["Uniform fabrics", "Stadium seating", "Shoe compounds"]'::jsonb),
    ('f1231c3e', 'In which system does the legislature choose the executive?', 'Parliamentary', '["Presidential", "Semi-presidential", "Confederal"]'::jsonb),
    ('f3d0fa4d', 'Which love-linked neurochemical occurs naturally in chocolate?', 'PEA', '["Serotonin", "Dopamine", "Endorphins"]'::jsonb),
    ('f6810619', 'Whose skeleton hangs in the Natural History Museum''s main hall?', 'A blue whale', '["A sperm whale", "A humpback whale", "A fin whale"]'::jsonb),
    ('fc95d58b', 'Which asbestos type was used for fireproofing before its ban?', 'Chrysotile', '["Fibreglass", "Ceramic fibre", "Silica gel"]'::jsonb),
