    ('fdbe7539', 'Which tool projects a laser line to check a wall is plumb?', 'Laser level', '["Tape measure", "Speed square", "Chalk line"]'::jsonb),
    ('fe48bcd2', 'Which hand adaptation lets primates grip and use tools?', 'Opposable thumbs', '["Color vision", "Long arms", "Prehensile tails"]'::jsonb),
    ('fe996b13', 'Which crocus-derived spice outpriced gold by weight in the 1300s?', 'Saffron', '["Cinnamon", "Cumin", "Paprika"]'::jsonb),
    ('ff9605e8', 'Which problems will quantum computers solve much faster?', 'Factoring large numbers', '["Every problem", "No problems", "Storing data"]'::jsonb)
